python3 -c "
import json
with open('outputs/01e_PARTIAL_W3B4_1771741517.json') as f:
    data = json.load(f)
props = data['properties']
meta = data['metadata']
print(f'Total properties: {len(props)}')
print(f'Metadata total: {meta[\"total_properties\"]}')
print(f'Match: {len(props) == meta[\"total_properties\"]}')
sev = {}
for p in props:
    sev[p['severity']] = sev.get(p['severity'], 0) + 1
print(f'By severity: {sev}')
print(f'Metadata by_severity: {meta[\"by_severity\"]}')
print(f'Sum severity: {sum(sev.values())}')
scope = {}
for p in props:
    s = p['reachability']['bug_bounty_scope'].replace('-', '_')
    scope[s] = scope.get(s, 0) + 1
print(f'By scope: {scope}')
elig = sum(1 for p in props if p.get('bug_bounty_eligible'))
print(f'Bug bounty eligible: {elig}')
# Validate field constraints
issues = []
for p in props:
    if not isinstance(p['covers'], str):
        issues.append(f'{p[\"property_id\"]}: covers not string')
    if len(p['text']) > 120:
        issues.append(f'{p[\"property_id\"]}: text too long ({len(p[\"text\"])})')
    if len(p['assertion']) > 200:
        issues.append(f'{p[\"property_id\"]}: assertion too long ({len(p[\"assertion\"])})')
    r = p['reachability']
    if set(r.keys()) != {'classification','entry_points','attacker_controlled','bug_bounty_scope'}:
        issues.append(f'{p[\"property_id\"]}: reachability has wrong keys: {set(r.keys())}')
    if len(r.get('entry_points',[])) > 3:
        issues.append(f'{p[\"property_id\"]}: too many entry_points')
if issues:
    print('ISSUES:')
    for i in issues: print(f'  {i}')
else:
    print('All field constraints pass!')
"

